     "出荷したのに入金が立っていない注文 ·【出荷日】基準 · "
     "判定の分界は **商品が日本を出たか**（配送状態が「集荷済」以降なら出たとみなす）· "
     "「損失」= 出荷後に取消/返金/実収≤0 → 商品も送料も戻らない。これが真の損失 · "
     "「出荷前の取消」= 集荷前に取消 → 在庫が戻るので **損失に入れない**。件数だけ見ればよい · "
     "「未突合」= プラットフォーム明細にその注文番号が無い → 原因が 3 種混在（取得範囲外 / 売上認識の周期待ち / 明細 API 未接続）。"
     "プラットフォーム別に切り分けてからでないと損失として読めません · "
