def _note_page() -> None:
    """別のページから入った run なら、言語切替で保っていた表の未保存編集を捨てる（原生 data_editor も表が消えれば捨てる）。
    同じページの rerun・言語切替の rerun では何もしない。"""
    from streamlit.runtime.scriptrunner import get_script_run_ctx
    ctx = get_script_run_ctx()
    page = ctx.page_script_hash if ctx else ""
    if st.session_state.get("_cms_page") != page:
        st.session_state["_cms_page"] = page
        from shared.editor_state import forget_all   # editor_state は i18n を import する → ここで遅延 import
        forget_all()


def lang_selector():
    """每个 page 调用一次。
    - 隐藏 Streamlit 默认（基于文件名的）sidebar 导航
    - sidebar 顶部紧凑横排：语言 toggle 左 + 今日日期右（占 1 行高）
    - 按三大块分组渲染可翻译导航（销售数据 / 订货决策 / 商品情报）
    """
    from datetime import datetime

    _note_page()

    # 1) 仅隐藏 Streamlit 默认（文件名）sidebar 导航——必须保留，否则会和自定义导航重复。
    #    其余侧栏造型（日期大字/语言胶囊/顶栏浮动）已移除，回到 Streamlit 原生外观。
    # 日期 + 语言选择：置顶·居中（Boss 2026-05-25）。
    # 语言选择 segmented_control(testid=stButtonGroup·从容器JS确认) + radio fallback 居中。
    # 关键：button group 是 fit-content inline-flex，必须 width:100% 撑满父容器后 justify-center 才生效。
    st.markdown(
        "<style>"
        "[data-testid='stSidebarNav']{display:none!important;}"
        "section[data-testid='stSidebar'] [data-testid='stSidebarUserContent']{padding-top:0.5rem;}"
        ".cms-date-big{text-align:center;line-height:1.25;margin:.1rem 0 0;font-size:1.5rem;}"
        ".cms-date-big .num{font-weight:700;font-size:1.9rem;}"
        ".cms-date-big .meta{font-size:.92em;color:#64748B;}"
        "section[data-testid='stSidebar'] [data-testid='stButtonGroup'],"
        "section[data-testid='stSidebar'] div[role='radiogroup']"
        "{display:flex!important;justify-content:center!important;width:100%!important;}"
        "</style>",
        unsafe_allow_html=True,
    )

    # 2) 紧凑顶栏 — 跨页持久化：query_params(?lang=ja) > session_state > 默认 zh
    options = list(LANGS.keys())  # 中文 / 日本語
    code_to_label = {v: k for k, v in LANGS.items()}  # zh→中文, ja→日本語

    qp = st.query_params
    cur_lang_code = qp.get("lang") or st.session_state.get("lang") or "zh"
    if cur_lang_code not in LANGS.values():
        cur_lang_code = "zh"
    cur_label = code_to_label[cur_lang_code]

    # widget key 与 session_state 同步（首次访问 / 跨页恢复）
    if st.session_state.get("lang_seg") != cur_label:
        st.session_state["lang_seg"] = cur_label

    now = datetime.now()
    if cur_lang_code == "ja":
        wd = ["月", "火", "水", "木", "金", "土", "日"][now.weekday()]
        date_html = (
            f'<div class="cms-date-big">'
            f'<span class="meta">{now.year}年 · {wd}曜日</span> '
            f'<span class="num">{now.month}/{now.day}</span>'
            f'</div>'
        )
    else:
        wd = ["周一", "周二", "周三", "周四", "周五", "周六", "周日"][now.weekday()]
        date_html = (
            f'<div class="cms-date-big">'
            f'<span class="meta">{now.year}年 · {wd}</span> '
            f'<span class="num">{now.month}/{now.day}</span>'
            f'</div>'
        )

    def _on_lang_change():
        picked = st.session_state.get("lang_seg") or cur_label
        new_code = LANGS.get(picked, "zh")
        st.session_state["lang"] = new_code
        # 同步到 URL query params（页面切换后能恢复）
        st.query_params["lang"] = new_code

    with st.sidebar:
        # 语言选择置顶（Boss 2026-05-25：日期退到语言下方，不再抢最顶位）
        try:
            st.segmented_control(
                "lang", options,
                key="lang_seg", label_visibility="collapsed",
                on_change=_on_lang_change,
            )
        except Exception:
            st.radio(
                "lang", options,
                horizontal=True, key="lang_seg",
                label_visibility="collapsed",
                on_change=_on_lang_change,
            )
        st.markdown(date_html, unsafe_allow_html=True)  # 日期在语言下方·居中

    # 同步本次 render 的 session_state.lang + query_params（即使没触发 on_change，保证一致）
    st.session_state["lang"] = cur_lang_code
    if qp.get("lang") != cur_lang_code:
        st.query_params["lang"] = cur_lang_code

    # JS 注入：让所有 sidebar page_link 的 href 自动带上 ?lang=xx，
    # 这样跨页跳转 URL 不会丢失语言（Streamlit page_link 默认不传 query params）
    # 用 components.v1.html → 生成 iframe，通过 window.parent.document 反向操作主文档
    import streamlit.components.v1 as _components
    _components.html(
        """
<script>
(function() {
    const top = window.parent;
    function patchLangLinks() {
        try {
            const cur = new URLSearchParams(top.location.search).get('lang') || 'zh';
            top.document.querySelectorAll('[data-testid="stSidebar"] a[href]').forEach(a => {
                try {
                    const u = new URL(a.href, top.location.origin);
                    if (u.origin === top.location.origin) {
                        u.searchParams.set('lang', cur);
                        if (a.href !== u.toString()) a.href = u.toString();
                    }
                } catch (e) {}
            });
        } catch (e) {}
    }
    patchLangLinks();
    setTimeout(patchLangLinks, 300);
    setTimeout(patchLangLinks, 1000);
    if (!top.__cmsLangLinkObs) {
        top.__cmsLangLinkObs = new MutationObserver(() => {
            clearTimeout(top.__cmsLangLinkTimer);
            top.__cmsLangLinkTimer = setTimeout(patchLangLinks, 100);
        });
        top.__cmsLangLinkObs.observe(top.document.body, {childList: true, subtree: true});
    }
})();
</script>
""",
        height=0, width=0,
    )

    # 3) 分组导航
    st.sidebar.divider()
    for group_label, pages in _NAV_GROUPS:
        if group_label is None:
            # 顶层直显（首页 / 设置）
            for path, label in pages:
                try:
                    st.sidebar.page_link(path, label=t(label))
                except Exception:
                    pass
        else:
            # 分组用 expander 包起来,默认展开
            with st.sidebar.expander(t(group_label), expanded=True):
                for path, label in pages:
                    try:
                        st.page_link(path, label=t(label))
                    except Exception:
                        pass

    return cur_lang_code


def get_lang() -> str:
    """返回当前语言代码 zh / ja"""
    return st.session_state.get("lang", "zh")


def t(text: str) -> str:
    """翻译。lang=ja 查 TRANSLATIONS_JA;lang=zh 查 TRANSLATIONS_ZH(把日文 key 还原中文)。
    都查不到则原样返回。
    """
    if get_lang() == "ja":
        return TRANSLATIONS_JA.get(text, text)
    return TRANSLATIONS_ZH.get(text, text)


